import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const mk = async () => (await createHost()) as any;

test('unknown books are refused and null', async () => {
  const h = await mk();
  assert.equal(await h.book('x'), null);
  for (const m of ['lend', 'giveBack', 'retire']) assert.equal((await h[m]('x')).ok, false);
  assert.equal(await h.book('x'), null);
  await h.__dispose();
});

test('lifecycle', async () => {
  const h = await mk();
  assert.deepEqual(await h.add('a'), { ok: true });
  assert.equal((await h.add('a')).ok, false);
  assert.deepEqual(await h.book('a'), { status: 'available', loans: 0 });
  assert.equal((await h.giveBack('a')).ok, false);
  assert.deepEqual(await h.lend('a'), { ok: true });
  assert.equal((await h.lend('a')).ok, false);
  assert.equal((await h.retire('a')).ok, false);
  assert.equal((await h.add('a')).ok, false);
  assert.deepEqual(await h.book('a'), { status: 'lent', loans: 1 });
  await h.giveBack('a'); await h.lend('a'); await h.giveBack('a'); await h.lend('a'); await h.giveBack('a');
  assert.deepEqual(await h.book('a'), { status: 'available', loans: 3 });
  assert.equal((await h.lend('a')).ok, false);
  assert.deepEqual(await h.retire('a'), { ok: true });
  assert.deepEqual(await h.book('a'), { status: 'retired', loans: 3 });
  for (const m of ['add', 'lend', 'giveBack', 'retire']) assert.equal((await h[m]('a')).ok, false);
  assert.deepEqual(await h.book('a'), { status: 'retired', loans: 3 });
  await h.__dispose();
});

